<form method="post"><?=csrf()?><input type="hidden" name="action" value="documents"><?php foreach(array_merge($settings['document_types'],[['key'=>'','name'=>'','required'=>false,'mimes'=>['application/pdf'],'max_mb'=>5]]) as $i=>$type):?><fieldset class="panel"><legend><?=me(__('manor.document_policy'))?> <?=me($i+1)?></legend><label><?=me(__('manor.document_key'))?><input name="doc_key[]" value="<?=me($type['key'])?>" pattern="[a-z_]{1,60}"></label><label><?=me(__('manor.document_name'))?><input name="doc_name[]" value="<?=me($type['name'])?>"></label><label class="check"><input type="checkbox" name="doc_required[<?=$i?>]" value="1" <?=$type['required']?'checked':''?>><?=me(__('manor.mandatory'))?></label><label><?=me(__('manor.maximum_mb'))?><input type="number" min="1" max="10" name="doc_size[]" value="<?=me($type['max_mb'])?>"></label><?php foreach(['application/pdf'=>'PDF','image/jpeg'=>'JPEG','image/png'=>'PNG'] as $mime=>$label):?><label class="check"><input type="checkbox" name="doc_mimes[<?=$i?>][]" value="<?=$mime?>" <?=in_array($mime,$type['mimes'],true)?'checked':''?>><?=$label?></label><?php endforeach?></fieldset><?php endforeach?><button><?=me(__('manor.save_policies'))?></button></form>
